=== e2e/README.md ===
# E2E Testing

Playwright browser tests covering all major features across 6 browser/device configurations.

```mermaid
graph TB
    FIX[fixtures.ts<br/>50+ helpers] --> SPECS["27 Spec Files"]
    UTIL[test-utils.ts<br/>storage, bin selection] --> FIX
    CFG[playwright.config.ts<br/>6 browsers, parallel] --> SPECS
    SPECS --> DT[Desktop<br/>Chromium, Firefox, WebKit]
    SPECS --> MB[Mobile<br/>Pixel 5, iPhone 12]
    SPECS --> TB[Tablet<br/>iPad gen 7]
```

## Key Files

| File                   | Purpose                                                                               |
| ---------------------- | ------------------------------------------------------------------------------------- |
| `fixtures.ts`          | Custom wait helpers, grid interaction, UI panel selectors, viewport constants         |
| `test-utils.ts`        | Storage isolation (`clearAllStorage`), auto-save polling, deterministic bin selection |
| `playwright.config.ts` | 6 browser projects, parallel execution, 0 retries                                     |

## Browser Matrix

| Project       | Device          | Viewport |
| ------------- | --------------- | -------- |
| chromium      | Desktop Chrome  | 1280×720 |
| firefox       | Desktop Firefox | 1280×720 |
| webkit        | Desktop Safari  | 1280×720 |
| mobile-chrome | Pixel 5         | 393×851  |
| mobile-safari | iPhone 12       | 390×844  |
| tablet        | iPad (gen 7)    | 810×1080 |

## Test Scaffold

```typescript
test.describe('Feature', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
    await clearAllStorage(page);
    await page.reload();
    await waitForAppReady(page);
  });

  test.afterEach(async ({ page }) => {
    await clearAllStorage(page);
    await resetViewport(page); // CRITICAL: prevents mobile pollution
  });
});
```

## Core Selectors

| Element      | Selector                                                         | Helper                     |
| ------------ | ---------------------------------------------------------------- | -------------------------- |
| Grid         | `[role="application"]`                                           | `getGrid()`                |
| Bins         | `[data-bin-id]`                                                  | `waitForBinCount()`        |
| Staging bins | `[data-staging-bin-id]`                                          | `waitForStagingBinCount()` |
| Inspector    | `[data-inspector]`                                               | `getInspector()`           |
| Sidebar      | `[data-sidebar]`                                                 | `getSidebar()`             |
| Dialogs      | `[role="dialog"]:not([aria-label="Labs experimental features"])` | `getActiveDialog()`        |
| Mobile nav   | `[data-bottom-nav]`                                              | `getBottomNav()`           |

## Grid Coordinates

```typescript
const bounds = await getGridBounds(page);
const screenX = bounds.x + gridX;
const screenY = bounds.y + gridY;
// Grid (0,0) = bottom-left, but mouse uses screen coords (top-left)

// Draw a bin via helper
const bin = await drawBinOnGrid(page, 50, 50, 100, 100);
```

## Gotchas

1. **Viewport pollution** — mobile tests set 375×667; must call `resetViewport()` in `afterEach` or cascading failures occur
2. **Labs drawer always in DOM** — has `[role="dialog"]`; use `getActiveDialog()` helper to exclude it
3. **Bin DOM order non-deterministic** — use `getBinByIndex(page, i)` instead of `.first()` / `.last()` for parallel safety
4. **Swap detection skipped** — Shift+drag requires precise bin centering; unreliable in E2E due to auto-zoom. Verified in unit tests
5. **Paint mode must exit** — call `waitForPaintModeExited()` before next grid interaction
6. **Auto-save polling** — use `waitForAutoSave()` not `page.waitForTimeout(2000)`; app debounces at 1000ms
7. **Multi-select Alt+drag flaky** — race condition between selection state and drag start; marked `test.skip()`
8. **3D canvas slow** — takes ~10s to load; use `waitForCanvas(page, 10000)` timeout
9. **0 retries policy** — flakes are root-caused, not masked; `retries: 0` in config
10. **Mouse steps matter** — use `{ steps: 5 }` for drag operations; too few = unreliable movement
=== add-bins.spec.ts ===
import {
  test,
  expect,
  waitForAppReady,
  getGridBounds,
  drawBinOnGrid,
  selectBinAt,
  getInspector,
  selectBinSize,
  getSidebar,
  waitForBinCount,
  waitForToast,
  waitForPaintModeExited,
  waitForBinSelected,
  clearAllStorage,
  resetViewport,
  getActiveDialog,
} from './fixtures';

test.describe('Add Bins Flow', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
    await waitForAppReady(page);
  });

  test.afterEach(async ({ page }) => {
    await clearAllStorage(page);
    await resetViewport(page);

    // Close any lingering dialogs
    const dialogs = getActiveDialog(page);
    if ((await dialogs.count()) > 0) {
      await page.keyboard.press('Escape');
      await dialogs.waitFor({ state: 'detached', timeout: 1000 }).catch(() => {});
    }
  });

  test('can add a bin by clicking on the grid', async ({ page }) => {
    // The grid should be visible
    const grid = page.locator('[role="application"]');
    await expect(grid).toBeVisible();

    // Click on the grid to add a bin
    const bounds = await getGridBounds(page);
    await page.mouse.click(bounds.x + 50, bounds.y + 50);

    // Wait for bin to appear
    await waitForBinCount(page, 1);
  });

  test('can select a bin size from palette', async ({ page }) => {
    // Find the size brush section (CollapsibleSection uses button with text, not heading)
    const sidebar = getSidebar(page);
    await expect(sidebar.getByRole('button', { name: /Size Brush/i })).toBeVisible();

    // Click on a 2x2 square size button
    await selectBinSize(page, 2, 2);

    // The paint mode indicator should be visible in toolbar
    await expect(page.getByText(/paint.*2×2/i)).toBeVisible();
  });

  test('can fill layer with uniform bins', async ({ page }) => {
    // Select a size first
    await selectBinSize(page, 2, 2);

    // Now click the "Fill with X×Y" button - look in the sidebar
    const sidebar = getSidebar(page);
    const fillButton = sidebar.getByRole('button', { name: /fill.*2.*2/i });
    await expect(fillButton).toBeVisible();
    await fillButton.click();

    // Should see a toast notification about bins added
    await waitForToast(page, /added.*bins/i);
  });

  test('shows bin inspector when bin is selected', async ({ page }) => {
    // Fill the layer with 2x2 bins to have something to select
    await selectBinSize(page, 2, 2);
    const sidebar = getSidebar(page);
    const fillButton = sidebar.getByRole('button', { name: /fill.*2.*2/i });
    await fillButton.click();

    // Wait for bins to be added
    await waitForToast(page, /added.*bins/i);

    // Exit paint mode with Escape
    await page.keyboard.press('Escape');
    await waitForPaintModeExited(page);

    // Click on the grid where a bin should be
    await selectBinAt(page, 50, 50);

    // The inspector should show bin details
    const inspector = getInspector(page);
    await expect(inspector.getByRole('heading', { name: /^\d×\d Bin$/i })).toBeVisible({
      timeout: 3000,
    });
  });

  test('can draw a bin by dragging on grid', async ({ page }) => {
    // Make sure we're not in paint mode
    await page.keyboard.press('Escape');
    await waitForPaintModeExited(page);

    // Draw a bin
    const bin = await drawBinOnGrid(page, 20, 20, 100, 100);

    // Should see a bin created - the inspector should show selection
    const inspector = getInspector(page);
    // Look for size notation like "3×3 Bin" in the inspector header
    await expect(inspector.getByRole('heading', { name: /\d×\d Bin/i })).toBeVisible({
      timeout: 3000,
    });

    // Verify the bin is selected
    await waitForBinSelected(bin);
  });

  test('bin list shows placed bins', async ({ page }) => {
    // Fill layer with bins
    await selectBinSize(page, 2, 2);
    const sidebar = getSidebar(page);
    const fillButton = sidebar.getByRole('button', { name: /fill.*2.*2/i });
    await fillButton.click();

    // Wait for bins to be added
    await waitForToast(page, /added.*bins/i);

    // Check the bin list section in the right panel
    const inspector = getInspector(page);
    await expect(inspector.getByRole('heading', { name: 'Bin List' })).toBeVisible();

    // Should show the bin size in the list
    await expect(inspector.getByText('2×2')).toBeVisible();
  });

  test('paint mode shows indicator in toolbar', async ({ page }) => {
    // Select a bin size
    await selectBinSize(page, 3, 3);

    // Paint mode indicator should be visible
    await expect(page.getByText(/paint.*3×3/i)).toBeVisible();

    // Press Escape to exit paint mode
    await page.keyboard.press('Escape');

    // Paint mode indicator should be hidden
    await waitForPaintModeExited(page);
  });
});

