    await expect(binsOnGrid).toBeVisible();

    // ...and the layout summary reflects the added bin.
    await expect(layerSummary).toHaveText('1% filled · 1 bins');

    // The bin occupies the single clicked cell. `grid-area` is the app's placement
    // mechanism onto baseplate cells, so it is the direct evidence of *where* the
    // bin landed; a generic visibility check cannot distinguish cell from cell.
    await expect(binsOnGrid).toHaveAttribute('aria-label', 'Bin 1 by 1, category Coral');
    await expect(binsOnGrid).toHaveAttribute('style', /grid-area: 3 \/ 3 \/ span 1 \/ span 1/);

